explanationMarkdown:
> **Thinking**
>
> A subarray may multiply a contiguous piece by $k$, divide a contiguous piece by $k$, or do nothing. $n\le 10^5$ requires a linear decision among “not started / multiplying / dividing / already finished”.
>
> $f[i][j]$ is the best sum ending at $i$ in state $j$. Transitions start, continue, or finish the scaled segment, and a new segment may begin from $0$. The answer is the max over states.
>
> After rolling, space is constant and time is $O(n)$.

We define $f[i][j]$ as the maximum subarray sum ending at $\textit{nums}[i]$ with current state $j$. There are $4$ states for $j$:

- State $0$: the current subarray has not undergone any operation yet;
- State $1$: the current subarray is being multiplied by $k$;
- State $2$: the current subarray is being divided by $k$;
- State $3$: the operation on the current subarray has been completed.

Initially, $f[0][0] = 0$, and all other $f[i][j] = -\infty$.

Next, we consider the state transitions. For the $i$-th number $\textit{nums}[i]$, we can choose not to perform any operation, multiply by $k$, divide by $k$, or continue after the operation has been completed:

- If we perform no operation, then $f[i][0] = \max(f[i-1][0], 0) + \textit{nums}[i]$;
- If we multiply by $k$, then $f[i][1] = \max(f[i-1][0], f[i-1][1], 0) + \textit{nums}[i] \times k$;
- If we divide by $k$, then $f[i][2] = \max(f[i-1][0], f[i-1][2], 0) + \textit{trunc}(\textit{nums}[i]/k)$, where the quotient is rounded toward zero;
- If the operation has been completed, then $f[i][3] = \max(f[i-1][1], f[i-1][2], f[i-1][3]) + \textit{nums}[i]$.

We take the maximum among all states as the answer.

The time complexity is $O(n)$, and the space complexity is $O(n)$, where $n$ is the length of the array $\textit{nums}$.

solutions.code:
class Solution {
    public long maxSubarraySum(int[] nums, int k) {
        int n = nums.length;
        long inf = Long.MIN_VALUE / 4;

        long[][] f = new long[n + 1][4];

        for (int i = 0; i <= n; i++) {
            Arrays.fill(f[i], inf);
        }

        f[0][0] = 0;
        long ans = inf;

        for (int i = 1; i <= n; i++) {
            long x = nums[i - 1];

            f[i][0] = Math.max(f[i - 1][0], 0) + x;
            f[i][1] = Math.max(Math.max(f[i - 1][0], f[i - 1][1]), 0) + x * k;
            f[i][2] = Math.max(Math.max(f[i - 1][0], f[i - 1][2]), 0) + (x / k);
            f[i][3] = Math.max(Math.max(f[i - 1][1], f[i - 1][2]), f[i - 1][3]) + x;

            ans = Math.max(ans, Math.max(Math.max(f[i][0], f[i][1]), Math.max(f[i][2], f[i][3])));
        }

        return ans;
    }
}

class Solution {
public:
    long long maxSubarraySum(vector<int>& nums, int k) {
        int n = nums.size();
        long long inf = numeric_limits<long long>::min() / 4;

        vector<array<long long, 4>> f(n + 1);

        for (int i = 0; i <= n; i++) {
            f[i].fill(inf);
        }

        f[0][0] = 0;
        long long ans = inf;

        for (int i = 1; i <= n; i++) {
            long long x = nums[i - 1];

            f[i][0] = max(f[i - 1][0], 0LL) + x;
            f[i][1] = max({f[i - 1][0], f[i - 1][1], 0LL}) + x * k;
            f[i][2] = max({f[i - 1][0], f[i - 1][2], 0LL}) + (x / k);
            f[i][3] = max({f[i - 1][1], f[i - 1][2], f[i - 1][3]}) + x;

            ans = max(ans, *max_element(f[i].begin(), f[i].end()));
        }

        return ans;
    }
};

func maxSubarraySum(nums []int, k int) int64 {
	n := len(nums)
	inf := int64(math.MinInt64 / 4)

	f := make([][4]int64, n+1)
	for i := range f {
		for j := 0; j < 4; j++ {
			f[i][j] = inf
		}
	}

	f[0][0] = 0
	ans := inf

	for i := 1; i <= n; i++ {
		x := int64(nums[i-1])

		f[i][0] = max(f[i-1][0], 0) + x
		f[i][1] = max(max(f[i-1][0], f[i-1][1]), 0) + x*int64(k)
		f[i][2] = max(max(f[i-1][0], f[i-1][2]), 0) + x/int64(k)
		f[i][3] = max(max(f[i-1][1], f[i-1][2]), f[i-1][3]) + x

		ans = max(ans, max(max(f[i][0], f[i][1]), max(f[i][2], f[i][3])))
	}

	return ans
}

function maxSubarraySum(nums: number[], k: number): number {
    const n = nums.length;
    const inf = -1e18;

    const f: number[][] = Array.from({ length: n + 1 }, () => {
        const arr = new Array(4).fill(inf);
        return arr;
    });

    f[0][0] = 0;
    let ans = inf;

    for (let i = 1; i <= n; i++) {
        const x = nums[i - 1];

        f[i][0] = Math.max(f[i - 1][0], 0) + x;
        f[i][1] = Math.max(Math.max(f[i - 1][0], f[i - 1][1]), 0) + x * k;
        f[i][2] = Math.max(Math.max(f[i - 1][0], f[i - 1][2]), 0) + Math.trunc(x / k);
        f[i][3] = Math.max(Math.max(f[i - 1][1], f[i - 1][2]), f[i - 1][3]) + x;

        ans = Math.max(ans, Math.max(...f[i]));
    }

    return ans;
}
